WITH base AS (SELECT * FROM inventory WHERE YEAR(last_restock) = 2023), summary AS (SELECT QUARTER(last_restock) AS last_restock_quarter, product_id, MAX(quantity) AS max_quantity, MIN(last_restock) AS min_last_restock FROM base GROUP BY QUARTER(last_restock), product_id) SELECT last_restock_quarter, max_quantity, min_last_restock FROM summary ORDER BY max_quantity DESC, last_restock_quarter;
